import React, { useEffect, useState } from 'react';
import Layout from '../components/Layout';

function ProfilePage() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  return (
    <Layout>
      <main className="relative pt-16 bg-background min-h-screen p-container-margin">
        <div className="flex flex-col w-full gap-section-gap">
          <div className="flex flex-col gap-unit">
            <span className="font-label-caps text-on-surface-variant tracking-widest text-primary">ACCOUNT</span>
            <h1 className="font-display-lg text-on-surface">Profile</h1>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-gutter relative">
            <div className="col-span-12 lg:col-span-8 group relative z-10">
              <div className="bg-surface-container-low/60 backdrop-blur-xl border border-glass-stroke rounded-3xl p-8 h-full flex flex-col justify-between overflow-hidden relative shadow-2xl">
                <div className="flex flex-col gap-6 items-center">
                  <div className="w-24 h-24 rounded-full bg-gradient-to-br from-electric-blue to-vibrant-violet flex items-center justify-center shadow-[0_0_20px_rgba(139,92,246,0.4)]">
                    <span className="material-symbols-outlined text-4xl text-white">person</span>
                  </div>
                  <div className="text-center">
                    <h2 className="font-headline-lg text-on-surface mb-1">{user?.email || 'Guest User'}</h2>
                    <p className="text-on-surface-variant font-data-mono">System Administrator</p>
                  </div>
                  <button className="mt-4 px-6 py-3 bg-surface-container border border-glass-stroke text-on-surface rounded-lg hover:bg-surface-container-highest transition-colors">
                    Edit Profile
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>
    </Layout>
  );
}

export default ProfilePage;
